import{_ as t,H as d,f as r,i as a}from"./chunks/framework.DWsZwgB4.js";const u=JSON.parse('{"title":"What is it?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),o={name:"guide/index.md"};function i(s,e,c,n,l,h){return d(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="what-is-it" tabindex="-1">What is it? <a class="header-anchor" href="#what-is-it" aria-label="Permalink to &quot;What is it?&quot;">​</a></h1><p>typeorm-extension covers the parts of a deployment that TypeORM leaves to you:</p><ul><li><strong>Create, drop and check</strong> the database on every supported driver, from code or the CLI.</li><li><strong>Detect schema drift</strong> between the migrations and the entities, and repair it with guarded, resumable helpers.</li><li><strong>Lock</strong>: a named advisory lock to run work like migrations in one replica at a time, and a row lock for read-modify-write.</li><li><strong>Classify driver errors</strong>: recognize a unique or foreign key violation or a lock conflict, whichever driver raised it.</li><li><strong>Seed</strong> the database with seeder classes and factories, optionally tracked so each seeder runs once.</li><li><strong>Manage data sources</strong>: find <code>data-source.ts</code> automatically and use one or many instances by alias.</li></ul><h2 id="supported-drivers" tabindex="-1">Supported drivers <a class="header-anchor" href="#supported-drivers" aria-label="Permalink to &quot;Supported drivers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Driver</th><th>Create / drop / check</th><th>Notes</th></tr></thead><tbody><tr><td><code>postgres</code></td><td>yes</td><td></td></tr><tr><td><code>cockroachdb</code></td><td>yes</td><td></td></tr><tr><td><code>mysql</code>, <code>mariadb</code></td><td>yes</td><td></td></tr><tr><td><code>mssql</code></td><td>yes</td><td></td></tr><tr><td><code>oracle</code></td><td>create and check</td><td><code>dropDatabase</code> does nothing on oracle</td></tr><tr><td><code>mongodb</code></td><td>yes</td><td>creates a database lazily, so <code>checkDatabase</code> reports it as existing once connected</td></tr><tr><td><code>better-sqlite3</code></td><td>yes</td><td>the database is a file</td></tr></tbody></table><p>TypeORM 1.0 removed the legacy <code>sqlite</code> driver; use <code>better-sqlite3</code>.</p>',6)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
